package group16.webapp.common.entity;

import jakarta.persistence.Column;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;

/**
 * Primary key shared by every table: {@code id BIGINT GENERATED BY DEFAULT AS IDENTITY}
 * (team decision 2026-11-17: BIGINT, not UUID).
 *
 * Extend {@link AuditableEntity} instead when the ERD table has both created_at and updated_at.
 * Tables with only created_at (availability_rules, notifications, ai_request_logs) extend this class
 * and declare their own {@code @CreatedDate Instant createdAt} plus
 * {@code @EntityListeners(AuditingEntityListener.class)}.
 */
@MappedSuperclass
public abstract class BaseEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id", nullable = false, updatable = false)
    private Long id;

    public Long getId() { return id; }
}
